"""One-shot HPC submitter. Upload to the active CPU Jupyter, then run manually.

This file embeds the frozen reviewed encoder. The exclusive receipt and job-name
queue check prevent accidental duplicate GPU requests. No automatic cancellation,
resubmission, extension or requeue is performed after an uncertain outcome.
"""
from __future__ import annotations

import base64
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import re
import shlex
import subprocess
import sys


ROOT = Path("/scratch/xy3257/cv-phase2-20261020")
WORK = ROOT / "gate-confirmation-20261023"
JOB_NAME = "cv-gate-confirmation-20261023"
ENCODER_SHA256 = '44ee1fc4139aafe57cd1cf3333909557dccaf9f85b88b96e51cb991788ec120e'
ENCODER_BASE64 = ''
EXPECTED_SOURCE_SHA256 = {
    "envs.py": "64b07f972fc5144d5d13c7bd614c1c796d67a73521043efc57073454ac4c12a7",
    "encoders.py": "7a407ad8f03ecf58bac6dd0bd0fceca0aaabae1201298083fe7ccf3cb5aee871",
    "utils.py": "03b0c1fb7f52fc822523125e5fe813cf48883459d48a038ffb22aa7ff87aef14",
}
NORMALIZATION_SHA256 = "2ecbe84ae1555e2e8f5fae49e49bab02fd5475f31ff7b4e4694e19791c61a690"
OLD_MANIFEST_SHA256 = "7188bd6de6b54eaaff75d22c8d3c631a1467f1d6e5b14c19bd1c269c37ee0d05"


def file_hash(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def clean_environment(environ):
    # Do not inherit SBATCH_* or SLURM_* options from the active CPU Jupyter job.
    return {name: environ[name] for name in ("PATH", "HOME", "USER", "LOGNAME", "LANG", "LC_ALL", "SHELL")
            if name in environ}


def build_command(work):
    return ["/opt/slurm/bin/sbatch", "--parsable", "--export=ALL", "--no-requeue",
            "--job-name=" + JOB_NAME, "--account=csci_ga_2271-2026fa",
            "--partition=c12m85-a100-1", "--gres=gpu:1", "--cpus-per-task=4",
            "--mem=24G", "--time=00:20:00", "--chdir=" + str(work),
            "--output=" + str(work / "slurm-%j.log"), str(work / "encode.sbatch")]


def batch_text(work):
    python = ROOT / "venv/bin/python"
    command = [str(python), str(work / "encode_gate_confirmation.py"),
               "--repo-root", str(ROOT / "repo"),
               "--normalization", str(ROOT / "data/features/normalization.npz"),
               "--old-manifest", str(ROOT / "data/dataset/manifest.json"),
               "--prior-development-records", str(ROOT / "fresh-gate-20261022/dataset/records.json"),
               "--cache-dir", str(ROOT / "cache/ijepa"),
               "--output", str(work / "dataset"), "--batch-size", "2"]
    packing = r'''
import hashlib, json, os, sys, zipfile
from pathlib import Path
work = Path(sys.argv[1])
data = work / "dataset"
manifest = json.loads((data / "manifest.json").read_text())
if manifest.get("status") != "completed" or manifest.get("episodes") != 192:
    raise RuntimeError("Refuse to package an incomplete encoding run")
if str(manifest["hardware"]["slurm_job_id"]) != os.environ.get("SLURM_JOB_ID"):
    raise RuntimeError("Encoding hardware proof belongs to another Slurm job")
def digest_file(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()
if digest_file(work / "encode_gate_confirmation.py") != manifest["helper_sha256"]:
    raise RuntimeError("Encoder source changed after execution")
for relative, expected in manifest["artifact_sha256"].items():
    path = (data / relative).resolve()
    if not path.is_relative_to(data.resolve()) or digest_file(path) != expected:
        raise RuntimeError("Encoded artifact changed before packaging: " + relative)
destination = work / "gate-confirmation-data.zip"
partial = work / "gate-confirmation-data.zip.partial"
if destination.exists() or partial.exists() or (work / "zip_receipt.json").exists():
    raise RuntimeError("A packaging artifact already exists; inspect instead of overwriting")
with zipfile.ZipFile(partial, "x", compression=zipfile.ZIP_DEFLATED, compresslevel=1, allowZip64=True) as archive:
    for path in sorted(data.rglob("*")):
        if path.is_file():
            archive.write(path, str(path.relative_to(data)))
    for name in ("encode_gate_confirmation.py", "encode.sbatch", "submission_driver.py", "submission_receipt.json"):
        archive.write(work / name, "execution_source/" + name)
with zipfile.ZipFile(partial) as archive:
    if archive.testzip() is not None:
        raise RuntimeError("Zip integrity check failed")
# Hard-link publication is exclusive: unlike rename it cannot replace a file.
os.link(partial, destination)
partial.unlink()
receipt = {"status": "completed", "slurm_job_id": os.environ["SLURM_JOB_ID"],
           "zip_path": str(destination), "zip_bytes": destination.stat().st_size,
           "zip_sha256": digest_file(destination), "manifest_sha256": digest_file(data / "manifest.json"),
           "episodes": 192, "independent_pairs": 96, "actual_gpu_uuid": manifest["hardware"]["actual_gpu_uuid"]}
with (work / "zip_receipt.json").open("x") as stream:
    json.dump(receipt, stream, indent=2)
print(json.dumps(receipt, indent=2), flush=True)
'''
    lines = ["#!/bin/bash", "set -euo pipefail", "umask 077",
             "export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=4 VECLIB_MAXIMUM_THREADS=1",
             "export CUBLAS_WORKSPACE_CONFIG=:4096:8 HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 PYTHONUNBUFFERED=1",
             shlex.join(command), shlex.join([str(python), "-", str(work)]) + " <<'FRESH_GATE_PACK'",
             packing, "FRESH_GATE_PACK", ""]
    return "\n".join(lines)


def main():
    if not ROOT.is_dir() or not (ROOT / "repo").is_dir() or not (ROOT / "venv/bin/python").is_file():
        raise RuntimeError("Run on the existing xy3257 HPC workspace; this script does not create a new environment")
    WORK.mkdir(parents=True, exist_ok=True)
    receipt = WORK / "submission_receipt.json"
    if receipt.exists():
        raise RuntimeError("Submission receipt exists; inspect it instead of submitting again: " + str(receipt))
    env = clean_environment(os.environ)
    active = subprocess.check_output(["/opt/slurm/bin/squeue", "-h", "-u", "xy3257", "-n", JOB_NAME, "-o", "%i %T"],
                                     text=True, cwd=ROOT, env=env, timeout=30).strip()
    if active:
        raise RuntimeError("An identically named job is already visible; refusing duplicate: " + active)
    encoder = base64.b64decode(ENCODER_BASE64, validate=True)
    if hashlib.sha256(encoder).hexdigest() != ENCODER_SHA256:
        raise RuntimeError("Embedded reviewed encoder source checksum mismatch")
    for name, expected in EXPECTED_SOURCE_SHA256.items():
        if file_hash(ROOT / "repo/experiments/predictor/control/src/phase1" / name) != expected:
            raise RuntimeError("Inherited phase1 source differs: " + name)
    if file_hash(ROOT / "data/features/normalization.npz") != NORMALIZATION_SHA256:
        raise RuntimeError("Original train normalization checksum mismatch")
    if file_hash(ROOT / "data/dataset/manifest.json") != OLD_MANIFEST_SHA256:
        raise RuntimeError("Original dataset metadata checksum mismatch")
    if not (ROOT / "cache/ijepa").is_dir():
        raise RuntimeError("Existing local I-JEPA cache is absent")
    command = build_command(WORK)
    record = {"status": "preparing", "created_utc": datetime.now(timezone.utc).isoformat(),
              "job_name": JOB_NAME, "command": command, "encoder_sha256": ENCODER_SHA256,
              "inherited_source_sha256": EXPECTED_SOURCE_SHA256,
              "normalization_sha256": NORMALIZATION_SHA256,
              "exported_environment_names": sorted(env),
              "excluded_scheduler_option_names": sorted(name for name in os.environ if name.startswith(("SBATCH_", "SLURM_"))),
              "gpu_execution_verified": False, "scientific_phase2_completed": False}
    # This is the concurrency barrier. Any partial preparation or unknown sbatch
    # outcome leaves a receipt that blocks a second invocation.
    with receipt.open("x") as stream:
        json.dump(record, stream, indent=2)
    try:
        with (WORK / "encode_gate_confirmation.py").open("xb") as stream:
            stream.write(encoder)
        with (WORK / "submission_driver.py").open("xb") as stream:
            stream.write(Path(__file__).read_bytes())
        with (WORK / "encode.sbatch").open("x") as stream:
            stream.write(batch_text(WORK))
        record["sbatch_sha256"] = file_hash(WORK / "encode.sbatch")
        record["status"] = "submitting"
        receipt.write_text(json.dumps(record, indent=2) + "\n")
        result = subprocess.run(command, env=env, cwd=WORK, text=True, capture_output=True, timeout=60)
        record.update(returncode=result.returncode, stdout=result.stdout, stderr=result.stderr)
        job = result.stdout.strip().split(";")[0]
        if result.returncode == 0 and re.fullmatch(r"[0-9]+", job):
            record.update(status="submitted", job_id=job)
        else:
            record["status"] = "submission_failed_or_ambiguous"
    except BaseException as exc:
        record.update(status="preparation_failed_or_submission_ambiguous", error=f"{type(exc).__name__}: {exc}")
        receipt.write_text(json.dumps(record, indent=2) + "\n")
        print(json.dumps(record, indent=2), flush=True)
        raise
    receipt.write_text(json.dumps(record, indent=2) + "\n")
    print(json.dumps(record, indent=2), flush=True)
    if record["status"] != "submitted":
        raise SystemExit(1)
    try:
        detail = subprocess.check_output(["/opt/slurm/bin/scontrol", "show", "job", record["job_id"]],
                                         text=True, cwd=WORK, env=env, timeout=30)
        print(detail, flush=True)
    except subprocess.SubprocessError as exc:
        print("Job was submitted; scheduler readback failed without resubmission: " + str(exc), flush=True)


if __name__ == "__main__":
    main()
